            {
                try
                {
                    _ = await AgentRpcServiceHandler.InvokeAsync<AgentChatContentDiscard, AgentRpcEmpty>(
                        client,
                        endpoint,
                        AgentChatProviderRpc.ServiceId,
                        "discard-content",
                        new(reference.Id),
                        CancellationToken.None).ConfigureAwait(false);
