                _ = await AgentRpcServiceHandler.InvokeAsync<AgentChatContentChunk, AgentRpcEmpty>(
                    client,
                    endpoint,
                    AgentChatProviderRpc.ServiceId,
                    "stage-content",
                    new(
                        reference,
                        offset,
                        Convert.ToBase64String(content.Data.Span.Slice(offset, length)),
                        offset + length == content.Data.Length),
                    cancellationToken).ConfigureAwait(false);
            }
            return reference;
        }
        catch
        {
            try
            {
                _ = await AgentRpcServiceHandler.InvokeAsync<AgentChatContentDiscard, AgentRpcEmpty>(
                    client,
                    endpoint,
                    AgentChatProviderRpc.ServiceId,
                    "discard-content",
                    new(reference.Id),
                    CancellationToken.None).ConfigureAwait(false);
            }
            catch
            {
            }
            throw;
        }
